Script:
// Run OCR on an image URL at ocr.space and report the recognised text.
// Browser-scope macro: no desktop/XModule needed.

const IMAGE_URL = 'https://ui.vision/content/images/ui.vision.logo2.webp';

uiv.setVar('!TIMEOUT_WAIT', 30);

uiv.goto('https://ocr.space/');

// 1) The page starts in "file upload" mode - switch it to URL mode so the
//    text field for the image address becomes usable.
const urlTab = uiv.$('xpath=//a[contains(., "URL") or contains(., "url")]', { required: false, timeout: 3 });

// 2) Put the image URL into the "Enter URL here" field.
const urlField = uiv.getByLabel('Enter URL here', { required: false, timeout: 5 })
    || uiv.$('id=imageUrl', { timeout: 10 });

uiv.page.fill(urlField, IMAGE_URL);
const typed = uiv.$('id=imageUrl').value;
if (typed !== IMAGE_URL) throw new Error(`URL did not stick in the field, got: ${typed}`);
uiv.log(`Image URL set: ${typed}`, 'blue');

// 3) WEBP image in, plain text out (fastest option), English.
uiv.page.selectOption('id=ocrFiletype', 'WEBP');
uiv.page.selectOption('id=ocrLanguage', 'English');
uiv.page.check('id=NoSearchable');

// 4) Start the recognition (trusted click - the page ignores synthetic ones
//    on some builds, and this button is the whole point of the macro).
uiv.browser.click('css=#btnStartOCR > a.btn');
uiv.log('OCR started, waiting for the result...', 'blue');

// 5) Wait for the result box to actually FILL (not merely exist).
const result = uiv.$('id=txtAreaParsedResult', { hasText: true, timeout: 90 });
const text = result.value.trim();

// Report it, and fail loudly if the service returned nothing/ an error banner.
uiv.log('=== OCR RESULT ================================================', 'green');
uiv.log(text || '(empty)', 'green');
uiv.log('===============================================================', 'green');

if (!text) throw new Error('OCR finished but the result text area is empty.');

const err = uiv.$('id=Error', { required: false, timeout: 0 });
if (err && err.visible) uiv.log(`Warning - the page shows an error banner: ${err.text}`, 'red');

uiv.banner(`OCR done for ${IMAGE_URL}<br><br><b>${text.length} characters recognised.</b>`, { tone: 'green' });
